scenario.irule:
when ACCESS_SAML_AUTHN { set authn [ACCESS::saml authn]; ACCESS::saml authn "${authn}|seen" }
when ACCESS_SAML_ASSERTION { set assertion [ACCESS::saml assertion]; ACCESS::saml assertion "${assertion}|seen" }
when ACCESS_SAML_SLO_REQ { set req [ACCESS::saml slo_req]; ACCESS::saml slo_req "${req}|seen" }
when ACCESS_SAML_SLO_RESP { set resp [ACCESS::saml slo_resp]; ACCESS::saml slo_resp "${resp}|seen" }
when HTTP_REQUEST { set authn [ACCESS::saml authn]; ACCESS::saml authn "${authn}|seen"; set assertion [ACCESS::saml assertion]; ACCESS::saml assertion "${assertion}|seen"; set req [ACCESS::saml slo_req]; ACCESS::saml slo_req "${req}|seen"; set resp [ACCESS::saml slo_resp]; ACCESS::saml slo_resp "${resp}|seen"; ACCESS::restrict_irule_events enable; ACCESS::restrict_irule_events disable; ACCESS::enable; ACCESS::acl eval /Common/restricted; ACCESS::respond 451 content blocked; ACCESS::disable; log local0. "saml=[ACCESS::saml assertion] acl=[ACCESS::acl result]" }
